// features/lifecycle.feature: After a replacement, only the new document waits for review
import { expect, expectStatus, test } from "../../fixtures";

test("after a replacement, only the new document waits for review", { tag: "@LIF-05" }, async ({ factory, apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const { vendor, extractions } = await factory.vendorInReview();
  await expectStatus(
    await reviewer.post(`/api/extractions/${extractions.insurance_certificate.id}/decision`, {
      data: { decision: "approve" },
    }),
    200,
  );
  await expectStatus(
    await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, { data: { decision: "approve" } }),
    200,
  );
  await expectStatus(
    await reviewer.post(`/api/extractions/${extractions.w9.id}/decision`, {
      data: { decision: "reject", note: "Wrong TIN, please re-upload" },
    }),
    200,
  );

  // Act
  const replacement = await factory.upload(vendor.id, "w9");
  await expect
    .poll(
      async () => (await expectStatus(await member.get(`/api/documents/${replacement.id}`), 200)).status,
      { message: "the replacement w9 is extracted", timeout: 30_000 },
    )
    .toBe("extracted");
  const submitted = await expectStatus(await member.post(`/api/vendors/${vendor.id}/submit`), 200);

  // Assert
  expect(submitted.status).toBe("in_review");
  const stored = await expectStatus(await member.get(`/api/vendors/${vendor.id}`), 200);
  expect(stored.status).toBe("in_review");
  const queue = await expectStatus<
    { vendor_id: string; extractions: { kind: string; document_id: string; status: string }[] }[]
  >(await reviewer.get("/api/review-queue"), 200);
  const items = queue.filter((item) => item.vendor_id === vendor.id);
  expect(items, "the vendor is listed once in the review queue").toHaveLength(1);
  expect(items[0].extractions).toHaveLength(1);
  expect(items[0].extractions[0].kind).toBe("w9");
  expect(items[0].extractions[0].document_id).toBe(replacement.id);
  expect(items[0].extractions[0].status).toBe("pending_review");
});
